<?php require 'includes/functions.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT b.*,m.title,m.poster,s.show_date,s.show_time,t.name theater,sc.name screen,u.name FROM bookings b JOIN shows s ON s.id=b.show_id JOIN movies m ON m.id=s.movie_id JOIN screens sc ON sc.id=s.screen_id JOIN theaters t ON t.id=sc.theater_id JOIN users u ON u.id=b.user_id WHERE b.id=? AND b.user_id=?');$q->execute([$id,$_SESSION['user']['id']]);$b=$q->fetch();if(!$b)exit('Ticket not found');$q=db()->prepare('SELECT seat_number FROM booked_seats WHERE booking_id=?');$q->execute([$id]);$seats=implode(', ',$q->fetchAll(PDO::FETCH_COLUMN));$pageTitle='Your ticket';require 'includes/header.php';?>
<div class="container py-5 col-lg-8"><div id="ticket" class="ticket shadow"><div class="ticket-head p-4 d-flex justify-content-between"><div><small>ADMIT ONE</small><h2 class="mb-0"><?=e($b['title'])?></h2></div><i class="fa-solid fa-ticket fs-1"></i></div><div class="p-4 row align-items-center"><div class="col-md-3"><img class="img-fluid rounded" src="<?=e(movie_poster($b))?>" alt=""></div><div class="col-md-6"><p class="mb-2"><strong>Guest:</strong> <?=e($b['name'])?></p><p class="mb-2"><strong>Theater:</strong> <?=e($b['theater'])?> · <?=e($b['screen'])?></p><p class="mb-2"><strong>When:</strong> <?=date('D, d M Y · g:i A',strtotime($b['show_date'].' '.$b['show_time']))?></p><p class="mb-2"><strong>Seats:</strong> <?=e($seats)?></p><p class="mb-0"><strong>Booking ID:</strong> <?=e($b['booking_code'])?></p></div><div class="col-md-3 text-center"><img class="qr" src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=<?=urlencode($b['booking_code'])?>" alt="QR"><small class="d-block">Scan at entry</small></div></div></div><div class="mt-4 d-flex gap-2"><button class="btn btn-gradient" onclick="window.print()"><i class="fa fa-print"></i> Print ticket</button><button class="btn btn-outline-light" onclick="window.print()">Save as PDF</button></div></div><?php require 'includes/footer.php'; ?>
